def wiggleSort(nums):
    # Iterate through the array, up to n-2
    for i in range(len(nums) - 1):
        # For even index, enforce nums[i] ≤ nums[i+1]
        if i % 2 == 0:
            if nums[i] > nums[i+1]:
                nums[i], nums[i+1] = nums[i+1], nums[i]
        # For odd index, enforce nums[i] ≥ nums[i+1]
        else:
            if nums[i] < nums[i+1]:
                nums[i], nums[i+1] = nums[i+1], nums[i]
